// ClientsGrowthSchema.js — FRONTEND schema: labels, formulas, remarks, click-throughs. Generated by gen-report.js from report.map (same folder).
// The numbers come from the backend twin app/api/mda4/reports/clients/growth/list/ClientsGrowthSchema.js (same measure keys).
import { getApiRoutes } from '../../../AppRoutes/apiRoutesHandler';
import ClientsGrowthActions from './logicControl/actionsRegistry';
const apiRoutes = getApiRoutes();

export const ClientsGrowthSchema = {
  entity: 'simukopa_clients_growth',
  label: 'Client Growth',
  description: '',
  apiBase: apiRoutes.clientsgrowth?.base,
  moduleRole: 'view_reports',
  currency: 'KES',
  actionRegistry: ClientsGrowthActions,

  groupBy: 'month',
  groupLabel: 'Month',
  groupByOptions: [{ key: 'month', label: 'Month' }, { key: 'year', label: 'Year' }],

  fields: [
    { key: 'new_clients', label: 'New Clients', from: 'clients' },
    { key: 'chg', label: 'vs Previous', calc: 'change(new_clients)' },
  ],

  remarks: [
    { if: 'new_clients == 0', tone: 'watch', title: 'No new clients', say: 'No clients registered in {label}.' },
    { if: 'chg !== null && chg <= -25', tone: 'watch', title: 'Slowing', say: '{label}: {new_clients} new clients, down {abs(chg)}% on {prev_label}.' },
    { if: 'true', tone: 'neutral', title: 'Registrations', say: '{new_clients} new clients registered in {label}.' },
  ],

  headline: '{label}: {new_clients} new clients[, {updown} {abs(chg)}% on {prev_label}].',

  // coming periods the report page adds after the history (see forecast.js)
  forecast: [{ key: 'new_clients', next: 7, method: 'auto', integer: true }],
};
